import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Test Flow: Inline Scripts in ForEach
export const flowWithForEachInlineScripts = Flow(
    {
        $id: Now.ID['test_flow_foreach_inline_scripts'],
        name: 'Test - ForEach with Inline Scripts',
        description: 'Test flow with inline scripts inside ForEach',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_foreach'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // ForEach with inline script
        wfa.flowLogic.forEach(
            wfa.dataPill(params.trigger.current.watch_list, 'array.string'),
            { $id: Now.ID['test_foreach_watchers'], annotation: 'Process each watcher with inline script' },
            (_watcher) => {
                wfa.action(
                    action.core.log,
                    { $id: Now.ID['test_log_watcher'], annotation: 'Log watcher notification with inline script' },
                    {
                        log_level: 'info',
                        log_message: wfa.inlineScript(`
                            var watcher = fd_data._5__for_each;
                            var reqNum = fd_data.trigger.current.number;
                            var watcherName = watcher.name || watcher.user_name || 'Unknown';
                            return 'Notifying watcher: ' + watcherName + ' about request ' + reqNum;
                        `),
                    }
                )
            }
        )
    }
)
